<?php
require_once 'config.php';
setCorsHeaders();

// API corrigée pour récupérer les évaluations avec positionnement correct
try {
    $db = getDB();
    
    // Vérifier l'authentification
    $payload = verifyToken();\n    $userId = $payload['user_id'];\n    \n    // Récupérer tous les textes de l'utilisateur avec leurs évaluations\n    $stmt = $db->prepare(\"\n        SELECT \n            t.id,\n            t.titre,\n            t.contenu,\n            t.langue,\n            t.theme,\n            t.nb_vers,\n            t.statut,\n            t.note,\n            t.commentaire,\n            t.created_at,\n            t.updated_at\n        FROM cp2i_textes t\n        WHERE t.participant_id = ?\n        ORDER BY t.created_at DESC\n    \");\n    \n    $stmt->execute([$userId]);\n    $textes = $stmt->fetchAll(PDO::FETCH_ASSOC);\n    \n    $result = [];\n    \n    foreach ($textes as $texte) {\n        $texteData = [\n            'id' => (int)$texte['id'],\n            'titre' => $texte['titre'],\n            'contenu' => $texte['contenu'],\n            'langue' => $texte['langue'],\n            'theme' => $texte['theme'],\n            'nb_vers' => (int)$texte['nb_vers'],\n            'statut' => $texte['statut'],\n            'note_finale' => $texte['note'] ? (float)$texte['note'] : null,\n            'commentaire_general' => $texte['commentaire'],\n            'created_at' => $texte['created_at'],\n            'updated_at' => $texte['updated_at'],\n            'corrections' => []\n        ];\n        \n        // Récupérer les évaluations détaillées depuis cp2i_evaluations\n        $evalStmt = $db->prepare(\"\n            SELECT \n                e.id,\n                e.correcteur_id,\n                e.pertinence,\n                e.coherence,\n                e.correction,\n                e.presentation,\n                e.note_totale,\n                e.remarques,\n                e.created_at as date_evaluation,\n                c.prenom as correcteur_prenom,\n                c.nom as correcteur_nom\n            FROM cp2i_evaluations e\n            LEFT JOIN cp2i_users c ON e.correcteur_id = c.id\n            WHERE e.texte_id = ?\n            ORDER BY e.created_at ASC\n        \");\n        \n        $evalStmt->execute([$texte['id']]);\n        $evaluations = $evalStmt->fetchAll(PDO::FETCH_ASSOC);\n        \n        // Si pas d'évaluations dans cp2i_evaluations, chercher dans cp2i_corrections\n        if (empty($evaluations)) {\n            $corrStmt = $db->prepare(\"\n                SELECT \n                    c.id,\n                    c.corrector_id as correcteur_id,\n                    c.note as note_totale,\n                    c.commentaire as remarques,\n                    c.created_at as date_evaluation,\n                    u.prenom as correcteur_prenom,\n                    u.nom as correcteur_nom,\n                    NULL as pertinence,\n                    NULL as coherence,\n                    NULL as correction,\n                    NULL as presentation\n                FROM cp2i_corrections c\n                LEFT JOIN cp2i_users u ON c.corrector_id = u.id\n                WHERE c.texte_id = ?\n                ORDER BY c.created_at ASC\n            \");\n            \n            $corrStmt->execute([$texte['id']]);\n            $evaluations = $corrStmt->fetchAll(PDO::FETCH_ASSOC);\n        }\n        \n        // Formater les évaluations\n        foreach ($evaluations as $eval) {\n            $correction = [\n                'id' => (int)$eval['id'],\n                'correcteur_id' => (int)$eval['correcteur_id'],\n                'correcteur_nom' => $eval['correcteur_prenom'] . ' ' . $eval['correcteur_nom'],\n                'note_totale' => $eval['note_totale'] ? (float)$eval['note_totale'] : null,\n                'commentaires' => $eval['remarques'],\n                'date_evaluation' => $eval['date_evaluation']\n            ];\n            \n            // Ajouter les notes détaillées si disponibles\n            if (isset($eval['pertinence'])) {\n                $correction['note_pertinence'] = $eval['pertinence'] ? (float)$eval['pertinence'] : null;\n                $correction['note_coherence'] = $eval['coherence'] ? (float)$eval['coherence'] : null;\n                $correction['note_correction'] = $eval['correction'] ? (float)$eval['correction'] : null;\n                $correction['note_presentation'] = $eval['presentation'] ? (float)$eval['presentation'] : null;\n            }\n            \n            $texteData['corrections'][] = $correction;\n        }\n        \n        // Calculer la note moyenne si pas de note finale\n        if (!$texteData['note_finale'] && !empty($texteData['corrections'])) {\n            $notes = array_filter(array_column($texteData['corrections'], 'note_totale'));\n            if (!empty($notes)) {\n                $texteData['note_finale'] = round(array_sum($notes) / count($notes), 2);\n            }\n        }\n        \n        // Déterminer le statut si pas défini\n        if (!$texteData['statut'] || $texteData['statut'] === 'en_attente') {\n            if ($texteData['note_finale']) {\n                $texteData['statut'] = $texteData['note_finale'] >= 10 ? 'accepte' : 'refuse';\n            } else {\n                $texteData['statut'] = 'en_attente';\n            }\n        }\n        \n        $result[] = $texteData;\n    }\n    \n    // Statistiques globales\n    $stats = [\n        'total_textes' => count($result),\n        'textes_avec_notes' => count(array_filter($result, function($t) { return $t['note_finale'] !== null; })),\n        'textes_acceptes' => count(array_filter($result, function($t) { return $t['statut'] === 'accepte'; })),\n        'textes_refuses' => count(array_filter($result, function($t) { return $t['statut'] === 'refuse'; })),\n        'textes_en_attente' => count(array_filter($result, function($t) { return $t['statut'] === 'en_attente'; }))\n    ];\n    \n    $notes = array_filter(array_column($result, 'note_finale'));\n    if (!empty($notes)) {\n        $stats['note_moyenne'] = round(array_sum($notes) / count($notes), 2);\n    } else {\n        $stats['note_moyenne'] = null;\n    }\n    \n    echo json_encode([\n        'success' => true,\n        'textes' => $result,\n        'stats' => $stats,\n        'debug' => [\n            'user_id' => $userId,\n            'timestamp' => date('Y-m-d H:i:s'),\n            'method' => 'fixed_positioning'\n        ]\n    ], JSON_PRETTY_PRINT);\n    \n} catch (Exception $e) {\n    http_response_code(500);\n    echo json_encode([\n        'success' => false,\n        'error' => 'Erreur lors de la récupération des évaluations: ' . $e->getMessage(),\n        'debug' => [\n            'file' => $e->getFile(),\n            'line' => $e->getLine(),\n            'trace' => $e->getTraceAsString()\n        ]\n    ], JSON_PRETTY_PRINT);\n}\n?>"